{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE VIEW RUBYSORGANICS_DB.MAPLEMONK.VW_SHOPIFY_PARSED_DISCOUNT_CODES AS WITH order_base AS ( SELECT ORDER_NAME, MAX(DISCOUNT_CODE) AS DISCOUNT_CODE, MAX(TAGS) AS TAGS FROM RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_SHOPIFY_FACT_ITEMS GROUP BY ORDER_NAME ), parsed_discount_applications AS ( SELECT ORDER_NAME, ARRAY_AGG( DISTINCT UPPER( TRIM( COALESCE( NULLIF(TRIM(f.value:code::STRING), \'\'), NULLIF(TRIM(f.value:title::STRING), \'\') ) ) ) ) AS APP_CODES FROM RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_SHOPIFY_FACT_ITEMS, LATERAL FLATTEN(INPUT => DISCOUNT_APPLICATIONS) f WHERE COALESCE(LOWER(f.value:target_type::STRING), \'line_item\') <> \'shipping_line\' AND COALESCE(NULLIF(TRIM(f.value:code::STRING), \'\'), NULLIF(TRIM(f.value:title::STRING), \'\')) IS NOT NULL GROUP BY ORDER_NAME ), parsed_note_attributes AS ( SELECT ORDER_NAME, ARRAY_AGG(DISTINCT UPPER(TRIM(SPLIT_PART(f.value:name::STRING, \'|\', 2)))) AS ATTR_CODES FROM RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_SHOPIFY_FACT_ITEMS, LATERAL FLATTEN(INPUT => NOTE_ATTRIBUTES) f WHERE LOWER(TRIM(f.value:name::STRING)) LIKE \'discount |%\' AND TRIM(SPLIT_PART(f.value:name::STRING, \'|\', 2)) <> \'\' GROUP BY ORDER_NAME ), parsed_tags AS ( SELECT ORDER_NAME, ARRAY_AGG(DISTINCT UPPER(TRIM(t.value::STRING))) AS TAG_CODES FROM RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_SHOPIFY_FACT_ITEMS, LATERAL FLATTEN(INPUT => SPLIT(TAGS, \',\')) t WHERE UPPER(TRIM(t.value::STRING)) IN ( \'BUNDLE3\', \'BUNDLE4\', \'HELLORUBY\', \'LIPDAYBOGO\', \'FIRST999\', \'RUBY999\', \'RUBYFLASH\', \'HELLOHYDRA\', \'MISSEDYA25\', \'MYSTERYGIFT\', \'VIP15\', \'EMPLOYEEDISCOUNT50\', \'FREEGIFT\', \'FREEMINIPUFF\', \'FREE MINI PUFF\', \'FREE PUFF (CONCEALER OFFER)\', \'FREE PUFF (COMPACT OFFER)\', \'FREE PUFF (FOUNDATION OFFER)\', \'BOGO\', \'MONSOON SALE: BOGO!\', \'MONSOON SALE: BOGO\', \'MONSOON SALE: BUY 1 GET 1 FREE\', \'FESTIVE SALE: BOGO\', \'FESTIVE SALE: BUY 1 GET 1 FREE\', \'PAYDAY SALE: BUY 1 GET 1 FREE\', \'SUMMER SALE - BUY 1 GET 1 FREE!\' ) OR UPPER(TRIM(t.value::STRING)) LIKE \'%BOGO%\' OR UPPER(TRIM(t.value::STRING)) LIKE \'%BUY 1 GET 1%\' GROUP BY ORDER_NAME ) SELECT b.ORDER_NAME, COALESCE( NULLIF( TRIM( ARRAY_TO_STRING( ARRAY_DISTINCT( ARRAY_CAT( COALESCE(na.ATTR_CODES, ARRAY_CONSTRUCT()), ARRAY_CAT( COALESCE(da.APP_CODES, ARRAY_CONSTRUCT()), ARRAY_CAT( CASE WHEN TRIM(COALESCE(b.DISCOUNT_CODE, \'\')) <> \'\' THEN ARRAY_CONSTRUCT(UPPER(TRIM(b.DISCOUNT_CODE))) ELSE ARRAY_CONSTRUCT() END, COALESCE(pt.TAG_CODES, ARRAY_CONSTRUCT()) ) ) ) ), \' + \' ) ), \'\' ), \'No discount\' ) AS ALL_DISCOUNT_CODES_APPLIED FROM order_base b LEFT JOIN parsed_discount_applications da ON b.ORDER_NAME = da.ORDER_NAME LEFT JOIN parsed_note_attributes na ON b.ORDER_NAME = na.ORDER_NAME LEFT JOIN parsed_tags pt ON b.ORDER_NAME = pt.ORDER_NAME; CREATE OR REPLACE TRANSIENT TABLE RUBYSORGANICS_DB.MAPLEMONK.TEMP_LINE_ITEM_BASE AS WITH mrp_master AS ( SELECT UPPER(TRIM(\"Product Title\")) AS PRODUCT_TITLE_CLEAN, MAX(COALESCE(TRY_TO_DOUBLE(REPLACE(\"MRP\"::STRING, \',\', \'\')), 0)) AS UNIT_MRP, MAX(COALESCE(TRY_TO_DOUBLE(REPLACE(\"FREEBIE COGS\"::STRING, \',\', \'\')), 0)) AS UNIT_FREEBIE_COGS, MAX(COALESCE(TRY_TO_DOUBLE(REPLACE(\"FREEBIE BOGO\"::STRING, \',\', \'\')), 0)) AS UNIT_FREEBIE_BOGO FROM RUBYSORGANICS_DB.MAPLEMONK.gs_mrp_cogs_sheet1 WHERE TRIM(COALESCE(\"Product Title\", \'\')) <> \'\' GROUP BY UPPER(TRIM(\"Product Title\")) ), line_item_props AS ( SELECT s.ORDER_NAME, s.LINE_ITEM_ID::STRING AS LINE_ITEM_ID, MAX( CASE WHEN LOWER(TRIM(p.value:name::STRING)) = \'freeitem\' AND LOWER(TRIM(p.value:value::STRING)) = \'true\' THEN 1 ELSE 0 END ) AS IS_FREE_ITEM_PROP FROM RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_SHOPIFY_FACT_ITEMS s, LATERAL FLATTEN(INPUT => s.LINE_ITEM_PROPERTIES) p GROUP BY s.ORDER_NAME, s.LINE_ITEM_ID::STRING ), order_refund_status AS ( SELECT ORDER_NAME, MAX(CASE WHEN LOWER(ORDER_STATUS) = \'cancelled\' THEN 1 ELSE 0 END) AS IS_CANCELLED_ORDER, SUM(ABS(COALESCE(QUANTITY, 0))) AS TOTAL_ORDERED_QTY, SUM( CASE WHEN IS_REFUND = 1 THEN ABS(COALESCE(NULLIF(REFUND_QUANTITY, 0), QUANTITY, 0)) ELSE 0 END ) AS TOTAL_REFUNDED_QTY, ABS(SUM(COALESCE(NULLIF(DISCOUNT, 0), DISCOUNT_BEFORE_TAX * 1.18, 0))) AS ORDER_TOTAL_DISCOUNT FROM RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_SHOPIFY_FACT_ITEMS GROUP BY ORDER_NAME ), line_base AS ( SELECT s.ORDER_NAME, s.ORDER_STATUS, UPPER(COALESCE(s.FINANCIAL_STATUS, \'UNKNOWN\')) AS FINANCIAL_STATUS, UPPER(COALESCE(s.FULFILLMENT_STATUS, \'UNFULFILLED\')) AS FULFILLMENT_STATUS, s.ORDER_TIMESTAMP::DATE AS ORDER_DATE, s.LINE_ITEM_ID::STRING AS LINE_ITEM_ID, TRIM(SPLIT_PART(s.PRODUCT_NAME, \' - \', 1)) AS BASE_PRODUCT_NAME, s.CATEGORY, COALESCE(lp.IS_FREE_ITEM_PROP, 0) AS IS_FREE_ITEM_PROP, ors.ORDER_TOTAL_DISCOUNT, CASE WHEN ors.IS_CANCELLED_ORDER = 0 AND ors.TOTAL_REFUNDED_QTY > 0 AND ors.TOTAL_REFUNDED_QTY < ors.TOTAL_ORDERED_QTY THEN 1 ELSE 0 END AS IS_PARTIAL_REFUND_ORDER, CASE WHEN ors.IS_CANCELLED_ORDER = 0 AND ors.TOTAL_REFUNDED_QTY > 0 AND ors.TOTAL_REFUNDED_QTY < ors.TOTAL_ORDERED_QTY THEN GREATEST( 0, COALESCE(s.QUANTITY, 0) - CASE WHEN s.IS_REFUND = 1 THEN ABS(COALESCE(NULLIF(s.REFUND_QUANTITY, 0), s.QUANTITY, 0)) ELSE 0 END ) WHEN s.IS_REFUND = 1 OR LOWER(s.ORDER_STATUS) = \'cancelled\' THEN -1 * ABS(COALESCE(NULLIF(s.REFUND_QUANTITY, 0), s.QUANTITY, 1)) WHEN COALESCE(s.QUANTITY, 0) = 0 THEN -1 * ABS(COALESCE(s.REFUND_QUANTITY, 1)) ELSE s.QUANTITY END AS EFFECTIVE_QTY, CASE WHEN s.IS_REFUND = 1 OR LOWER(s.ORDER_STATUS) = \'cancelled\' THEN -1 * ABS(COALESCE(NULLIF(s.REFUND_QUANTITY, 0), s.QUANTITY, 1)) WHEN COALESCE(s.QUANTITY, 0) = 0 THEN -1 * ABS(COALESCE(s.REFUND_QUANTITY, 1)) ELSE 0 END AS REVERSED_QTY, CASE WHEN ors.IS_CANCELLED_ORDER = 0 AND ors.TOTAL_REFUNDED_QTY > 0 AND ors.TOTAL_REFUNDED_QTY < ors.TOTAL_ORDERED_QTY THEN (COALESCE(s.GROSS_SALES_AFTER_TAX, s.TOTAL_SALES, 0) - COALESCE(s.DISCOUNT, 0)) * DIV0( GREATEST( 0, COALESCE(s.QUANTITY, 0) - CASE WHEN s.IS_REFUND = 1 THEN ABS(COALESCE(NULLIF(s.REFUND_QUANTITY, 0), s.QUANTITY, 0)) ELSE 0 END ), NULLIF(COALESCE(s.QUANTITY, 0), 0) ) WHEN s.IS_REFUND = 1 OR LOWER(s.ORDER_STATUS) = \'cancelled\' THEN -1 * ABS(COALESCE(s.GROSS_SALES_AFTER_TAX, s.TOTAL_SALES, 0) - COALESCE(s.DISCOUNT, 0)) ELSE COALESCE(s.GROSS_SALES_AFTER_TAX, s.TOTAL_SALES, 0) - COALESCE(s.DISCOUNT, 0) END AS PAID_SELLING_PRICE, s.GROSS_SALES_BEFORE_TAX, s.GROSS_SALES_AFTER_TAX, s.TOTAL_SALES, s.QUANTITY, s.DISCOUNT, s.DISCOUNT_BEFORE_TAX, s.TAX, s.IS_REFUND, s.REFUND_QUANTITY, dc.ALL_DISCOUNT_CODES_APPLIED FROM RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_SHOPIFY_FACT_ITEMS s LEFT JOIN RUBYSORGANICS_DB.MAPLEMONK.VW_SHOPIFY_PARSED_DISCOUNT_CODES dc ON s.ORDER_NAME = dc.ORDER_NAME LEFT JOIN line_item_props lp ON s.ORDER_NAME = lp.ORDER_NAME AND s.LINE_ITEM_ID::STRING = lp.LINE_ITEM_ID LEFT JOIN order_refund_status ors ON s.ORDER_NAME = ors.ORDER_NAME ), enriched AS ( SELECT l.*, COALESCE(m.UNIT_MRP, 0) AS UNIT_MRP, COALESCE(m.UNIT_FREEBIE_COGS, 0) AS UNIT_FREEBIE_COGS, COALESCE(m.UNIT_FREEBIE_BOGO, 0) AS UNIT_FREEBIE_BOGO, SUM(CASE WHEN COALESCE(m.UNIT_MRP, 0) > 0 THEN ABS(l.EFFECTIVE_QTY) ELSE 0 END) OVER (PARTITION BY l.ORDER_NAME) AS ORDER_NON_GWP_QTY, SUM(CASE WHEN l.IS_FREE_ITEM_PROP = 1 AND COALESCE(m.UNIT_MRP, 0) > 0 THEN ABS(l.EFFECTIVE_QTY) ELSE 0 END) OVER (PARTITION BY l.ORDER_NAME) AS ORDER_FREE_PROP_QTY, SUM(ABS(l.PAID_SELLING_PRICE)) OVER (PARTITION BY l.ORDER_NAME) AS ORDER_ABS_PAID_TOTAL FROM line_base l LEFT JOIN mrp_master m ON UPPER(TRIM(l.BASE_PRODUCT_NAME)) = m.PRODUCT_TITLE_CLEAN ) SELECT e.*, CASE WHEN e.IS_FREE_ITEM_PROP = 1 AND e.ORDER_TOTAL_DISCOUNT > 0 AND ABS(e.EFFECTIVE_QTY) > 0 AND e.UNIT_MRP > 0 AND e.UNIT_FREEBIE_BOGO > 0 THEN CASE WHEN e.ORDER_FREE_PROP_QTY >= e.ORDER_NON_GWP_QTY AND e.ORDER_ABS_PAID_TOTAL > 0.01 AND ABS(e.EFFECTIVE_QTY) >= 2 THEN FLOOR(ABS(e.EFFECTIVE_QTY) / 2) WHEN e.ORDER_FREE_PROP_QTY >= e.ORDER_NON_GWP_QTY AND e.ORDER_ABS_PAID_TOTAL > 0.01 AND ABS(e.EFFECTIVE_QTY) = 1 THEN 0 ELSE ABS(e.EFFECTIVE_QTY) END ELSE 0 END AS PROP_FREE_BOGO_QTY, CASE WHEN e.IS_FREE_ITEM_PROP = 0 AND ( UPPER(e.ALL_DISCOUNT_CODES_APPLIED) LIKE \'%BOGO%\' OR UPPER(e.ALL_DISCOUNT_CODES_APPLIED) LIKE \'%BUY 1 GET 1%\' ) AND ABS(e.EFFECTIVE_QTY) > 0 AND ABS(e.PAID_SELLING_PRICE) <= 0.01 AND COALESCE(e.TAX, 0) = 0 AND ABS(COALESCE(e.DISCOUNT, 0)) > 0 AND e.UNIT_FREEBIE_BOGO > 0 AND e.UNIT_MRP > 0 AND ABS( ABS(e.DISCOUNT) - (ROUND(ABS(e.DISCOUNT) / e.UNIT_MRP) * e.UNIT_MRP) ) <= GREATEST(2.0, 0.002 * ABS(e.DISCOUNT)) THEN LEAST( ABS(e.EFFECTIVE_QTY), GREATEST(1, ROUND(ABS(e.DISCOUNT) / e.UNIT_MRP)) ) ELSE 0 END AS EXPLICIT_FREE_BOGO_QTY FROM enriched e; CREATE OR REPLACE TRANSIENT TABLE RUBYSORGANICS_DB.MAPLEMONK.TEMP_SOLVED_BOGO_LINES AS WITH order_note_attrs AS ( SELECT ORDER_NAME, NOTE_ATTRIBUTES FROM RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_SHOPIFY_FACT_ITEMS QUALIFY ROW_NUMBER() OVER (PARTITION BY ORDER_NAME ORDER BY LINE_ITEM_ID) = 1 ), note_attr_bogo_discount AS ( SELECT o.ORDER_NAME, SUM(COALESCE(TRY_TO_DOUBLE(f.value:value::STRING), 0)) AS ATTR_BOGO_DISCOUNT FROM order_note_attrs o, LATERAL FLATTEN(INPUT => o.NOTE_ATTRIBUTES) f WHERE LOWER(TRIM(f.value:name::STRING)) LIKE \'discount |%\' AND ( UPPER(SPLIT_PART(f.value:name::STRING, \'|\', 2)) LIKE \'%BOGO%\' OR UPPER(SPLIT_PART(f.value:name::STRING, \'|\', 2)) LIKE \'%BUY 1 GET 1%\' ) GROUP BY o.ORDER_NAME ), order_totals AS ( SELECT ORDER_NAME, ABS(SUM(COALESCE(NULLIF(DISCOUNT, 0), DISCOUNT_BEFORE_TAX * 1.18, 0))) AS FULL_ORDER_DISCOUNT, GREATEST(0, SUM(ABS(EFFECTIVE_QTY) * UNIT_MRP) - ABS(SUM(PAID_SELLING_PRICE))) AS EFFECTIVE_MRP_DISCOUNT, MIN(CASE WHEN UNIT_MRP > 0 OR UNIT_FREEBIE_COGS > 0 THEN 1 ELSE 0 END) AS ALL_LINES_MAPPED FROM RUBYSORGANICS_DB.MAPLEMONK.TEMP_LINE_ITEM_BASE WHERE UPPER(ALL_DISCOUNT_CODES_APPLIED) LIKE \'%BOGO%\' OR UPPER(ALL_DISCOUNT_CODES_APPLIED) LIKE \'%BUY 1 GET 1%\' GROUP BY ORDER_NAME HAVING SUM(PROP_FREE_BOGO_QTY) = 0 AND SUM(EXPLICIT_FREE_BOGO_QTY) = 0 AND SUM(IS_FREE_ITEM_PROP) = 0 ), orders_needing_solve AS ( SELECT b.ORDER_NAME, COALESCE(NULLIF(na.ATTR_BOGO_DISCOUNT, 0), ot.FULL_ORDER_DISCOUNT) AS PRIMARY_TARGET_DISCOUNT, CASE WHEN ot.ALL_LINES_MAPPED = 1 AND ot.EFFECTIVE_MRP_DISCOUNT > 0 THEN ot.EFFECTIVE_MRP_DISCOUNT ELSE 0 END AS FALLBACK_MRP_TARGET_DISCOUNT, ARRAY_AGG( OBJECT_CONSTRUCT( \'line_id\', b.LINE_ITEM_ID, \'mrp\', b.UNIT_MRP, \'bogo_cogs\', b.UNIT_FREEBIE_BOGO, \'unit_sales\', ROUND(ABS(COALESCE(b.TOTAL_SALES, b.PAID_SELLING_PRICE, 0)) / NULLIF(ABS(b.EFFECTIVE_QTY), 0), 2), \'unit_paid\', ROUND(ABS(COALESCE(b.PAID_SELLING_PRICE, 0)) / NULLIF(ABS(b.EFFECTIVE_QTY), 0), 2), \'qty\', ABS(b.EFFECTIVE_QTY) ) ) WITHIN GROUP ( ORDER BY b.UNIT_FREEBIE_BOGO ASC, ROUND(ABS(COALESCE(b.TOTAL_SALES, b.PAID_SELLING_PRICE, 0)) / NULLIF(ABS(b.EFFECTIVE_QTY), 0), 2) ASC, b.LINE_ITEM_ID ASC ) AS ITEMS_JSON FROM RUBYSORGANICS_DB.MAPLEMONK.TEMP_LINE_ITEM_BASE b INNER JOIN order_totals ot ON b.ORDER_NAME = ot.ORDER_NAME LEFT JOIN note_attr_bogo_discount na ON b.ORDER_NAME = na.ORDER_NAME WHERE b.UNIT_FREEBIE_BOGO > 0 AND b.UNIT_MRP > 0 AND ABS(b.EFFECTIVE_QTY) > 0 GROUP BY b.ORDER_NAME, COALESCE(NULLIF(na.ATTR_BOGO_DISCOUNT, 0), ot.FULL_ORDER_DISCOUNT), CASE WHEN ot.ALL_LINES_MAPPED = 1 AND ot.EFFECTIVE_MRP_DISCOUNT > 0 THEN ot.EFFECTIVE_MRP_DISCOUNT ELSE 0 END ), udf_primary AS ( SELECT ORDER_NAME, ITEMS_JSON, FALLBACK_MRP_TARGET_DISCOUNT, PARSE_JSON( RUBYSORGANICS_DB.MAPLEMONK.SOLVE_BOGO_SUBSET_SUM_JS( ITEMS_JSON::STRING, PRIMARY_TARGET_DISCOUNT::FLOAT ) ) AS PRIMARY_SOLVED_ARRAY FROM orders_needing_solve WHERE PRIMARY_TARGET_DISCOUNT > 0 ), udf_execution AS ( SELECT ORDER_NAME, CASE WHEN ARRAY_SIZE(PRIMARY_SOLVED_ARRAY) > 0 THEN PRIMARY_SOLVED_ARRAY WHEN FALLBACK_MRP_TARGET_DISCOUNT > 0 THEN PARSE_JSON( RUBYSORGANICS_DB.MAPLEMONK.SOLVE_BOGO_SUBSET_SUM_JS( ITEMS_JSON::STRING, FALLBACK_MRP_TARGET_DISCOUNT::FLOAT ) ) ELSE PRIMARY_SOLVED_ARRAY END AS SOLVED_LINE_IDS_ARRAY FROM udf_primary ), flattened_lines AS ( SELECT u.ORDER_NAME, f.value::STRING AS FREE_LINE_ITEM_ID FROM udf_execution u, LATERAL FLATTEN(INPUT => u.SOLVED_LINE_IDS_ARRAY) f ) SELECT ORDER_NAME, FREE_LINE_ITEM_ID, COUNT(*) AS SOLVED_FREE_BOGO_QTY FROM flattened_lines GROUP BY ORDER_NAME, FREE_LINE_ITEM_ID; CREATE OR REPLACE TABLE RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_LINE_ITEM_DISCOUNTING_FACT AS SELECT b.ORDER_NAME, b.ORDER_DATE, b.LINE_ITEM_ID, b.BASE_PRODUCT_NAME, b.ORDER_STATUS, b.FINANCIAL_STATUS, b.FULFILLMENT_STATUS, b.UNIT_MRP, b.UNIT_FREEBIE_COGS, b.UNIT_FREEBIE_BOGO, b.EFFECTIVE_QTY AS QTY, b.REVERSED_QTY, b.PAID_SELLING_PRICE, b.IS_FREE_ITEM_PROP, b.IS_PARTIAL_REFUND_ORDER, LEAST( ABS(b.EFFECTIVE_QTY), CASE WHEN b.PROP_FREE_BOGO_QTY > 0 THEN b.PROP_FREE_BOGO_QTY WHEN b.EXPLICIT_FREE_BOGO_QTY > 0 THEN b.EXPLICIT_FREE_BOGO_QTY WHEN s.SOLVED_FREE_BOGO_QTY IS NOT NULL THEN s.SOLVED_FREE_BOGO_QTY ELSE 0 END ) AS FREE_BOGO_QTY, (b.EFFECTIVE_QTY - (SIGN(b.EFFECTIVE_QTY) * FREE_BOGO_QTY)) AS PAID_QTY, (FREE_BOGO_QTY * b.UNIT_FREEBIE_BOGO * SIGN(b.EFFECTIVE_QTY)) AS FREEBIE_BOGO_VALUE, (b.EFFECTIVE_QTY * b.UNIT_FREEBIE_COGS) AS FREEBIE_GWP_VALUE, ((b.EFFECTIVE_QTY - (SIGN(b.EFFECTIVE_QTY) * FREE_BOGO_QTY)) * b.UNIT_MRP) AS ADJUSTED_LINE_MRP_VALUE, b.ALL_DISCOUNT_CODES_APPLIED, b.IS_REFUND, b.REFUND_QUANTITY FROM RUBYSORGANICS_DB.MAPLEMONK.TEMP_LINE_ITEM_BASE b LEFT JOIN RUBYSORGANICS_DB.MAPLEMONK.TEMP_SOLVED_BOGO_LINES s ON b.ORDER_NAME = s.ORDER_NAME AND b.LINE_ITEM_ID = s.FREE_LINE_ITEM_ID; CREATE OR REPLACE TABLE RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_ORDER_DISCOUNTING_SUMMARY AS WITH order_aggregates AS ( SELECT ORDER_NAME, MIN(ORDER_DATE) AS ORDER_DATE, MAX(ALL_DISCOUNT_CODES_APPLIED) AS DISCOUNT_CODE, MAX(ORDER_STATUS) AS ORDER_STATUS, MAX(FINANCIAL_STATUS) AS FINANCIAL_STATUS, MAX(FULFILLMENT_STATUS) AS FULFILLMENT_STATUS, MAX(IS_PARTIAL_REFUND_ORDER) AS IS_PARTIAL_REFUND_ORDER, MAX(IS_FREE_ITEM_PROP) AS HAS_FREE_ITEM_PROP, SUM(PAID_SELLING_PRICE) AS PAID_TOTAL, SUM(ADJUSTED_LINE_MRP_VALUE) AS GROSS_MRP, SUM(FREEBIE_GWP_VALUE) AS TOTAL_FREEBIE_GWP, SUM(FREEBIE_BOGO_VALUE) AS TOTAL_FREEBIE_BOGO, SUM(QTY) AS SUM_OF_QUANTITY, SUM(REVERSED_QTY) AS SUM_OF_REVERSED_QUANTITY FROM RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_LINE_ITEM_DISCOUNTING_FACT GROUP BY ORDER_NAME ) SELECT ORDER_NAME, ORDER_DATE, DISCOUNT_CODE, ORDER_STATUS, FINANCIAL_STATUS, FULFILLMENT_STATUS, CASE WHEN LOWER(ORDER_STATUS) = \'cancelled\' THEN \'CANCELLED\' WHEN LOWER(FINANCIAL_STATUS) = \'refunded\' THEN \'FULLY_REFUNDED\' WHEN LOWER(FINANCIAL_STATUS) = \'partially_refunded\' OR IS_PARTIAL_REFUND_ORDER = 1 THEN \'PARTIALLY_REFUNDED\' ELSE \'ACTIVE\' END AS ORDER_REFUND_STATUS, CASE WHEN ABS(PAID_TOTAL) < 0.01 AND ( UPPER(DISCOUNT_CODE) LIKE \'%BOGO%\' OR UPPER(DISCOUNT_CODE) LIKE \'%BUY 1 GET 1%\' OR HAS_FREE_ITEM_PROP = 1 ) THEN 1 ELSE 0 END AS ZERO_TOTAL_BOGO_FLAG, CASE WHEN ZERO_TOTAL_BOGO_FLAG = 1 THEN 0 ELSE PAID_TOTAL END AS TOTAL, CASE WHEN ZERO_TOTAL_BOGO_FLAG = 1 THEN 0 ELSE GROSS_MRP END AS MRP, CASE WHEN ZERO_TOTAL_BOGO_FLAG = 1 THEN 0 ELSE (GROSS_MRP - PAID_TOTAL) END AS DISCOUNT, CASE WHEN ZERO_TOTAL_BOGO_FLAG = 1 OR GROSS_MRP = 0 THEN 0 ELSE (GROSS_MRP - PAID_TOTAL) / NULLIF(GROSS_MRP, 0) END AS DISCOUNT_PCT, CASE WHEN ZERO_TOTAL_BOGO_FLAG = 1 THEN 0 ELSE TOTAL_FREEBIE_GWP END AS FREEBIE_GWP, CASE WHEN ZERO_TOTAL_BOGO_FLAG = 1 THEN 0 ELSE TOTAL_FREEBIE_BOGO END AS FREEBIE_BOGO, CASE WHEN ZERO_TOTAL_BOGO_FLAG = 1 THEN 0 ELSE ((GROSS_MRP - PAID_TOTAL) + TOTAL_FREEBIE_GWP + TOTAL_FREEBIE_BOGO) END AS TOTAL_DISCOUNT_PLUS_FREEBIE, CASE WHEN ZERO_TOTAL_BOGO_FLAG = 1 OR GROSS_MRP = 0 THEN 0 ELSE ((GROSS_MRP - PAID_TOTAL) + TOTAL_FREEBIE_GWP + TOTAL_FREEBIE_BOGO) / NULLIF(GROSS_MRP, 0) END AS TOTAL_DISCOUNT_PLUS_FREEBIE_PCT, CASE WHEN ZERO_TOTAL_BOGO_FLAG = 1 THEN 0 ELSE SUM_OF_QUANTITY END AS SUM_OF_QUANTITY, CASE WHEN ZERO_TOTAL_BOGO_FLAG = 1 THEN 0 ELSE SUM_OF_REVERSED_QUANTITY END AS SUM_OF_REVERSED_QUANTITY FROM order_aggregates;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from RUBYSORGANICS_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            